/******************************************************************************
*
* @file content.c: everything the program puts into DDR before it starts
*                  drawing: four 1280x720 background images, two colour-keyed
*                  sprite sheets, the alpha sprite and the glyph atlases.
*
* All of it is generated by the CPU at start-up, so the demo needs no SD card
* and no image files.  mem_delta exists only so the same code can be built on a
* PC and previewed (see tools/host_preview.c); on the target it stays 0.
*
******************************************************************************/
#include "bbshow.h"
#include "art.h"

static uint32_t mem_delta;

void content_set_delta(uint32_t d) { mem_delta = d; }

static inline uint16_t *P(uint32_t addr)
{
    return (uint16_t *)(uintptr_t)(addr + mem_delta);
}

static void put(uint32_t base, uint32_t stride, int x, int y, uint16_t c)
{
    P(base + (uint32_t)y * stride)[x] = c;
}

static uint16_t rgb(int r, int g, int b)
{
    return (uint16_t)(((r & 31) << 11) | ((g & 63) << 5) | (b & 31));
}

/* ------------------------------------------------------------ backgrounds */
static uint16_t img_px(int i, int x, int y)
{
    /* Note: no colour here may be exactly C_MAGENTA (0xF81F); that value is the
     * key colour of the sprite sheets and a stray match on screen looks like a
     * keying fault. */
    static const uint16_t bars[8] = {
        C_WHITE, C_YELLOW, C_CYAN, C_GREEN, 0x781Fu, C_RED, 0x001Fu, 0x0000u
    };
    switch (i) {
    case 0:
        return bars[(x >> 7) & 7];
    case 1: {
        int k = ((x >> 6) ^ (y >> 6)) & 1;
        int g = (y * 63) / 719;
        return k ? rgb(4, g >> 1, 31) : rgb(1, g >> 2, 14);
    }
    case 2: {
        int s = ((x + y) >> 3) & 63;
        return rgb(s >> 1, s, 63 - s);
    }
    default: {
        int dx = x - 640, dy = y - 360;
        int d = (dx * dx) / 256 + (dy * dy) / 256;
        int k = d & 511;
        if (k < 64)  return C_WHITE;
        if (k < 160) return rgb(31, 40, 10);
        if (k < 288) return rgb(20, 10, 31);
        return rgb(4, 20, 8);
    }
    }
}

static void gen_images(void)
{
    for (int i = 0; i < 4; i++) {
        uint32_t base = IMG_ADDR(i);
        for (int y = 0; y < SCREEN_H; y++) {
            uint32_t *p = (uint32_t *)P(base + (uint32_t)y * IMG_STRIDE);
            for (int x = 0; x < SCREEN_W; x += 2) {
                uint32_t a = img_px(i, x, y);
                uint32_t b = img_px(i, x + 1, y);
                *p++ = a | (b << 16);
            }
        }
    }
}

/* ---------------------------------------------------------- sprite shapes */
/* 0 = transparent, 1 = rim, 2 = body */
static int shape_px(int dx, int dy, int r, int type)
{
    int ax = dx < 0 ? -dx : dx;
    int ay = dy < 0 ? -dy : dy;
    int d2 = dx * dx + dy * dy;

    switch (type) {
    case 0:                                              /* ball */
        if (d2 < (r - 4) * (r - 4)) return 2;
        if (d2 < r * r)             return 1;
        return 0;
    case 1: {                                            /* diamond */
        int m = ax + ay;
        if (m < r - 5) return 2;
        if (m < r)     return 1;
        return 0;
    }
    case 2: {                                            /* square */
        int m = ax > ay ? ax : ay;
        if (m < r - 4) return 2;
        if (m < r)     return 1;
        return 0;
    }
    default:                                             /* ring */
        if (d2 < (r - 9) * (r - 9)) return 0;
        if (d2 < (r - 5) * (r - 5)) return 1;
        if (d2 < r * r)             return 2;
        return 0;
    }
}

static void gen_sheet48(void)
{
    static const uint16_t rim[8]  = { 0x0320u, 0x0333u, 0x9800u, 0xFFFFu,
                                      0x8C00u, 0x780Fu, 0xB300u, 0x0010u };
    static const uint16_t body[8] = { 0x07E0u, 0x07FFu, 0xF800u, 0xFFFFu,
                                      0xFFE0u, 0xF81Fu, 0xFD20u, 0x021Fu };

    for (int c = 0; c < 8; c++) {
        uint32_t base = SHEET48_ADDR + (uint32_t)c * (SHEET48_CELL * 2);
        for (int y = 0; y < SHEET48_CELL; y++)
            for (int x = 0; x < SHEET48_CELL; x++)
                put(base, SHEET48_STRIDE, x, y, C_MAGENTA);

        if (c == 3) {                                    /* player ship */
            for (int y = 0; y < SHEET48_CELL; y++) {
                int dy = y - 24;
                int hw = (dy + 24) * 18 / 47;            /* 0 at the nose, 18 at the tail */
                for (int x = 0; x < SHEET48_CELL; x++) {
                    int ax = x - 24;
                    if (ax < 0) ax = -ax;
                    if (ax > hw) continue;
                    put(base, SHEET48_STRIDE, x, y,
                        (ax > hw - 3) ? 0x041Fu : ((dy > 6) ? 0xFFFFu : 0x07FFu));
                }
            }
            for (int y = 16; y < 26; y++)                /* cockpit */
                for (int x = 20; x < 28; x++)
                    put(base, SHEET48_STRIDE, x, y, 0x0010u);
            continue;
        }
        for (int y = 0; y < SHEET48_CELL; y++)
            for (int x = 0; x < SHEET48_CELL; x++) {
                int v = shape_px(x - 24, y - 24, 22, c & 3);
                if (v) put(base, SHEET48_STRIDE, x, y, v == 1 ? rim[c] : body[c]);
            }
    }
}

static void gen_sheet32(void)
{
    static const uint16_t rim[8]  = { 0x0320u, 0x0333u, 0x9800u, 0x8C00u,
                                      0xB300u, 0x780Fu, 0xF800u, 0x0010u };
    static const uint16_t body[8] = { 0x07E0u, 0x07FFu, 0xF800u, 0xFFE0u,
                                      0xFFE0u, 0xF81Fu, 0xFFFFu, 0x021Fu };

    for (int c = 0; c < 8; c++) {
        uint32_t base = SHEET32_ADDR + (uint32_t)c * (SHEET32_CELL * 2);
        for (int y = 0; y < SHEET32_CELL; y++)
            for (int x = 0; x < SHEET32_CELL; x++)
                put(base, SHEET32_STRIDE, x, y, C_MAGENTA);

        for (int y = 0; y < SHEET32_CELL; y++)
            for (int x = 0; x < SHEET32_CELL; x++) {
                int v = shape_px(x - 16, y - 16, 15, c & 3);
                if (v) put(base, SHEET32_STRIDE, x, y, v == 1 ? rim[c] : body[c]);
            }
    }
}

/* Radial glow orbs for the sprite-limit scene.  Each 32x32 cell holds one hue as
 * a smooth falloff: a solid core for the first few pixels, then a ramp down to
 * near black, with everything outside the disc left magenta so the keyer removes
 * it.  The result blits as a round, soft-edged dot instead of a square. */
static uint16_t dim565(uint16_t c, int k)      /* k/8 of the original intensity */
{
    uint16_t r = (uint16_t)(((c >> 11) & 0x1Fu) * k / 8);
    uint16_t g = (uint16_t)(((c >> 5) & 0x3Fu) * k / 8);
    uint16_t b = (uint16_t)((c & 0x1Fu) * k / 8);
    return (uint16_t)((r << 11) | (g << 5) | b);
}

static void gen_orb32(void)
{
    static const uint16_t hue[ORB32_NCELL] = {
        0xFFFFu, 0x07FFu, 0x07E0u, 0xFFE0u, 0xFD20u, 0xF800u, 0xA81Fu, 0x4D3Fu
    };

    for (int c = 0; c < ORB32_NCELL; c++) {
        uint32_t base = ORB32_ADDR + (uint32_t)c * (ORB32_CELL * 2);
        for (int y = 0; y < ORB32_CELL; y++)
            for (int x = 0; x < ORB32_CELL; x++)
                put(base, ORB32_STRIDE, x, y, C_MAGENTA);

        for (int y = 0; y < ORB32_CELL; y++)
            for (int x = 0; x < ORB32_CELL; x++) {
                int dx = x - 16, dy = y - 16;
                int d2 = dx * dx + dy * dy;          /* 0 .. 2*16^2 */
                /* radius 11 so the whole disc fits inside the 24x24 centre
                 * crop the limit scene blits - at 15 the crop flattened the top
                 * and bottom of every orb into a chord */
                int r2 = 11 * 11;
                if (d2 > r2) continue;               /* stays keyed out */
                /* 8 = core, 1 = outer rim */
                int k = 9 - (d2 * 8) / r2;
                if (k < 1) k = 1;
                if (k > 8) k = 8;
                put(base, ORB32_STRIDE, x, y, dim565(hue[c], k));
            }
    }
}

static void gen_alpha96(void)
{
    static const uint16_t ramp[6] = { C_WHITE, C_CYAN, 0x0333u, 0x0210u, 0x0010u, 0x0008u };

    for (int y = 0; y < ALPHA96_CELL; y++)
        for (int x = 0; x < ALPHA96_CELL; x++) {
            int dx = x - 48, dy = y - 48;
            int ax = dx < 0 ? -dx : dx;
            int ay = dy < 0 ? -dy : dy;
            int m = ax > ay ? ax : ay;                   /* chebyshev radius 0..47 */
            int k = (m * 5) / 47;
            if (k > 5) k = 5;
            put(ALPHA96_ADDR, ALPHA96_STRIDE, x, y, ramp[k]);
        }
}

void content_init(void)
{
    gen_images();
    gen_sheet48();
    gen_sheet32();
    gen_orb32();
    gen_alpha96();
    hwt_init();
    hwt_init_big();
    art_set_delta(mem_delta);
    art_build();
}
